SELECT jsonb_build_object('observed_at',clock_timestamp(),'scope','production metadata only; no business rows or function invocation','views',(SELECT jsonb_agg(jsonb_build_object('name',c.relname,'owner',c.relowner::regrole::text,'options',c.reloptions,'acl',c.relacl::text,'definition',pg_get_viewdef(c.oid,true))) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relname IN ('public_stock','public_mixes') AND c.relkind='v'),'column_grants',(SELECT coalesce(jsonb_agg(jsonb_build_object('table',c.relname,'column',a.attname,'acl',a.attacl::text)),'[]'::jsonb) FROM pg_attribute a JOIN pg_class c ON c.oid=a.attrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relname IN ('public_stock','public_mixes') AND a.attnum>0 AND NOT a.attisdropped AND a.attacl IS NOT NULL),'role_memberships',(SELECT coalesce(jsonb_agg(jsonb_build_object('member',member::regrole::text,'role',roleid::regrole::text)),'[]'::jsonb) FROM pg_auth_members WHERE member IN ('anon'::regrole,'authenticated'::regrole)),'effective_privileges',(SELECT jsonb_agg(jsonb_build_object('role',r.role_name,'view',c.oid::regclass::text,'select',has_table_privilege(r.role_name,c.oid,'SELECT'),'insert',has_table_privilege(r.role_name,c.oid,'INSERT'),'update',has_table_privilege(r.role_name,c.oid,'UPDATE'),'delete',has_table_privilege(r.role_name,c.oid,'DELETE'))) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace CROSS JOIN (VALUES('anon'),('authenticated')) r(role_name) WHERE n.nspname='public' AND c.relname IN ('public_stock','public_mixes') AND c.relkind='v')) AS metadata;
